/**
 * Data-driven Argentina coverage map with the COMPLETE, authoritative province geometry.
 *
 * Geometry is embedded verbatim from argentina-map.svg (24 <path class="prov">,
 * viewBox 0 0 1000 2133, full precision — no province clipped or simplified).
 *
 * The 13 paths that carry a data-n in the source become NAMED provinces; the 11
 * without become CONTEXT geometry (Jujuy, Catamarca, La Rioja, San Juan, Mendoza,
 * San Luis, Neuquen, Rio Negro, Chubut, Santa Cruz, Tierra del Fuego). All 24 are
 * rendered — nothing is discarded.
 *
 * A NAMED province is COVERED (sky heat ramp by sqrt(count)) only when it has a
 * slug present in `counts` with value > 0. Named provinces without a /remates page
 * (Salta, Tucuman, Capital Federal) and every CONTEXT path render as faint zinc.
 *
 * Public interface is unchanged: `export function CoverageMap({ counts })`.
 */

interface Province {
  name: string
  d: string
  /** /remates/[slug] — only set for provinces that can have a remates page. */
  slug?: string
}

