const HEAT_FROM = { h: 203, s: 92, l: 22 } // low count → deep sky
const HEAT_TO = { h: 199, s: 96, l: 60 } // high count → bright sky

/** Linear sky ramp by normalized intensity (0..1). */
function heatColor(t: number): string {
  const c = Math.min(1, Math.max(0, t))
  const h = HEAT_FROM.h + (HEAT_TO.h - HEAT_FROM.h) * c
  const s = HEAT_FROM.s + (HEAT_TO.s - HEAT_FROM.s) * c
  const l = HEAT_FROM.l + (HEAT_TO.l - HEAT_FROM.l) * c
  return `hsl(${h.toFixed(0)} ${s.toFixed(0)}% ${l.toFixed(0)}%)`
}

interface Readout {
  name: string
  slug?: string
  count: number
  covered: boolean
}

export function CoverageMap({ counts }: { counts: Record<string, number> }) {
  // Resolve each named province against the live counts.
  const provinces = useMemo(
    () =>
      NAMED.map((p) => {
        const count = p.slug ? counts[p.slug] ?? 0 : 0
        return { ...p, count, covered: count > 0 }
      }),
    [counts]
  )

  const covered = provinces.filter((p) => p.covered)
  const maxCount = Math.max(1, ...covered.map((p) => p.count))
  const totalRemates = covered.reduce((s, p) => s + p.count, 0)

  // Default readout: the most active covered province.
  const top =
    covered.slice().sort((a, b) => b.count - a.count)[0] ?? provinces[0]
  const [active, setActive] = useState<Readout>({
    name: top.name,
    slug: top.slug,
    count: top.count,
    covered: top.covered,
  })

  // sqrt scaling so the long tail (Sgo. del Estero = 1) stays visible while the
  // leader (Buenos Aires) reads as the most intense, without washing out the rest.
  const intensity = (count: number) =>
    count <= 0 ? 0 : Math.sqrt(count) / Math.sqrt(maxCount)

  return (
    <div className="flex flex-col items-center gap-6 sm:flex-row sm:items-center sm:gap-10">
      <svg
        viewBox="0 0 1000 2133"
        className="h-[320px] w-auto shrink-0 sm:h-[400px]"
        role="img"
        aria-label={`Mapa de cobertura de Argentina: ${covered.length} provincias con remates indexados`}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Context provinces — faint, non-interactive */}
        {CONTEXT.map((d, i) => (
          <path key={`ctx-${i}`} d={d} fill="#17171a" stroke="#2a2a30" strokeWidth={1.5} />
        ))}

        {provinces.map((p) => {
          const isActive = active.name === p.name
          if (!p.covered) {
            // Named but no remates page / no counts → context, still hoverable for its name.
            return (
              <path
                key={p.name}
                d={p.d}
                fill={isActive ? '#202024' : '#17171a'}
                stroke={isActive ? '#3f3f46' : '#2a2a30'}
                strokeWidth={1.5}
                className="cursor-default transition-colors"
                onMouseEnter={() =>
                  setActive({ name: p.name, slug: p.slug, count: 0, covered: false })
                }
                tabIndex={0}
                onFocus={() =>
                  setActive({ name: p.name, slug: p.slug, count: 0, covered: false })
                }
                role="img"
                aria-label={`${p.name}: sin remates indexados`}
              />
            )
          }
          const fill = heatColor(intensity(p.count))
          return (
            <Link
              key={p.name}
              href={`/remates/${p.slug}`}
              aria-label={`Remates en ${p.name}: ${p.count}`}
              onMouseEnter={() =>
                setActive({ name: p.name, slug: p.slug, count: p.count, covered: true })
              }
              onFocus={() =>
                setActive({ name: p.name, slug: p.slug, count: p.count, covered: true })
              }
            >
              <path
                d={p.d}
                fill={fill}
                stroke={isActive ? '#fde68a' : 'rgba(0,0,0,0.35)'}
                strokeWidth={isActive ? 4 : 1.5}
                className="cursor-pointer transition-all"
                style={{ filter: isActive ? 'brightness(1.18)' : undefined }}
              />
            </Link>
          )
        })}
      </svg>

      {/* Readout / legend */}
      <div className="text-center sm:text-left">
        <div className="text-xxs font-terminal uppercase tracking-widest text-zinc-500">Cobertura</div>
        <div className="mt-1 flex items-baseline gap-2 justify-center sm:justify-start">
          <span className="text-3xl font-light tabular-nums text-zinc-100">{covered.length}</span>
          <span className="text-sm text-zinc-500">
            provincias · <span className="tabular-nums">{totalRemates}</span> remates
          </span>
        </div>

        <div className="mt-4 rounded-lg border border-sky-500/25 bg-sky-500/[0.04] px-4 py-3">
          <div className="text-lg font-semibold text-zinc-100">{active.name}</div>
          {active.covered ? (
            <>
              <div className="text-sm text-zinc-500">
                <span className="tabular-nums">{active.count}</span> remates indexados
              </div>
              {active.slug && (
                <Link
                  href={`/remates/${active.slug}`}
                  className="mt-1.5 inline-block text-sm font-medium text-accent hover:text-sky-300"
                >
                  Ver remates en {active.name} →
                </Link>
              )}
            </>
          ) : (
            <div className="text-sm text-zinc-600">sin remates indexados</div>
          )}
        </div>

        {/* Heat legend */}
        <div className="mt-4 flex items-center gap-2 justify-center sm:justify-start">
          <span className="text-xxs text-zinc-600">menos</span>
          <div
            className="h-2 w-28 rounded-full"
            style={{
              background: `linear-gradient(to right, ${heatColor(0)}, ${heatColor(0.5)}, ${heatColor(1)})`,
            }}
            aria-hidden="true"
          />
          <span className="text-xxs text-zinc-600">más remates</span>
        </div>

        <p className="mt-3 text-xxs text-zinc-600">Pasá el mouse o tocá una provincia.</p>
      </div>
    </div>
  )
}
